const resp=$input.first().json;
const list=(resp&&resp.QueryResponse&&Array.isArray(resp.QueryResponse.Payment))?resp.QueryResponse.Payment:[];
// Build payment-method map (QB returns refs with only an id, not always a name)
const pmResp=$('QB Payment Methods').first().json;
const pmList=(pmResp&&pmResp.QueryResponse&&Array.isArray(pmResp.QueryResponse.PaymentMethod))?pmResp.QueryResponse.PaymentMethod:[];
const pmById={};
for(const pm of pmList){ pmById[String(pm.Id)]={name:(pm.Name||''),type:String(pm.Type||'').toUpperCase()}; }
function classify(p){
  const refNum=(p.PaymentRefNum||'').toString().trim();
  const ref=p.PaymentMethodRef||null;
  let pmName=(ref&&ref.name)?String(ref.name):'';
  let pmType='';
  if(ref&&ref.value!=null&&pmById[String(ref.value)]){
    if(!pmName) pmName=pmById[String(ref.value)].name;
    pmType=pmById[String(ref.value)].type;
  }
  if(pmType==='CREDIT_CARD') return 'Credit Card';
  if(/credit|card|visa|master|amex|discover/i.test(pmName)) return 'Credit Card';
  if(pmName) return pmName;
  return refNum?'Check':'ACH';
}
const payments=[]; const invoiceIds=new Set();
for(const p of list){
  const refNum=(p.PaymentRefNum||'').toString().trim();
  const method=classify(p);
  const ids=[];
  const lineAmtByInv={}; const lineOrder=[];
  for(const ln of (p.Line||[])){
    const lnAmt=(ln&&ln.Amount!=null)?Number(ln.Amount):0;
    let attributed=false;
    for(const lt of (ln.LinkedTxn||[])){
      if(lt.TxnType==='Invoice'&&lt.TxnId){
        const id=String(lt.TxnId);
        ids.push(id);invoiceIds.add(id);
        if(!attributed){ // a QB payment line applies to one txn; attribute its amount once
          if(lineAmtByInv[id]==null){lineAmtByInv[id]=0;lineOrder.push(id);}
          lineAmtByInv[id]+=lnAmt;
          attributed=true;
        }
      }
    }
  }
  const invoiceLines=lineOrder.map(id=>({invoiceId:id,amount:Math.round((lineAmtByInv[id]||0)*100)/100}));
  payments.push({qbPaymentId:String(p.Id),refNum,amount:(p.TotalAmt!=null?Number(p.TotalAmt):null),method,txnDate:p.TxnDate||'',customerName:(p.CustomerRef&&p.CustomerRef.name)?p.CustomerRef.name:'',customerRefId:(p.CustomerRef&&p.CustomerRef.value)?String(p.CustomerRef.value):'',invoiceIds:ids,invoiceLines});
}
return {json:{payments,invoiceIds:Array.from(invoiceIds),count:payments.length}};

// Dress console rows in the Airtable row shape Build Work Items expects.
const items = ($json.items || []);
const out = items.map(r => ({ json: { id: r.review_item_id, fields: {
  QBPaymentId: r.qb_payment_id || '',
  CheckNumber: r.check_number || '',
  InvoiceNumber: r.invoice_number || '',
  Amount: r.amount || '',
  Status: r.status || ''
}}}));
// Never return [] — downstream must still run on an empty register.
if (!out.length) out.push({ json: { id: null, fields: null } });
return out;

const norm=$('Normalize Payments').first().json;
const payments=Array.isArray(norm.payments)?norm.payments:[];
const invResp=$('QB Invoice Numbers').first().json;
const invList=(invResp&&invResp.QueryResponse&&Array.isArray(invResp.QueryResponse.Invoice))?invResp.QueryResponse.Invoice:[];
const invById={};
for(const inv of invList){invById[String(inv.Id)]={docNumber:inv.DocNumber||'',total:(inv.TotalAmt!=null?Number(inv.TotalAmt):null),balance:(inv.Balance!=null?Number(inv.Balance):null),full:fullContract(inv)};}
function fullContract(invObj){
  if(!invObj||!Array.isArray(invObj.Line)) return null;
  let s=0, frac=false;
  for(const ln of invObj.Line){
    const dt=String((ln&&ln.DetailType)||'');
    if(dt==='DiscountLineDetail'&&ln.Amount!=null){ s-=Number(ln.Amount)||0; continue; }
    const dd=ln&&ln.SalesItemLineDetail;
    if(dt!=='SalesItemLineDetail'||!dd) continue;
    const qty=(dd.Qty!=null)?Number(dd.Qty):null;
    const unit=(dd.UnitPrice!=null)?Number(dd.UnitPrice):null;
    const a=(ln.Amount!=null)?Number(ln.Amount):0;
    const nm=String(((dd.ItemRef&&dd.ItemRef.name)||'')+' '+(ln.Description||''));
    const feeName=/credit\s*card|credit\s*c\s*%|cc\s*fee|card\s*fee|surcharge|processing\s*fee|convenience\s*fee/i.test(nm);
    const feeQty=(qty!=null&&qty>0&&qty<0.2);
    if(feeName||feeQty) continue; // payment-method fees are not part of the contract
    if(qty!=null&&qty>0&&qty<1&&unit!=null&&unit>0){ s+=unit; frac=true; }
    else s+=a;
  }
  if(!frac) return null;
  return Math.round(s*100)/100;
}
const rows=$('Rows As Register').all().map(it=>it.json).filter(r=>r&&r.id);
function money(v){const n=parseFloat(v);return isNaN(n)?null:Math.round(n*100)/100;}
function digitsOf(s){return String(s==null?'':s).replace(/[^0-9]/g,'');}
const notSuperseded=(r)=>String((r.fields&&r.fields.Status)||'')!=='superseded_split';
const out=[];
const claimed=new Set();
for(const p of payments){
  const amt=money(p.amount);
  const lines=Array.isArray(p.invoiceLines)?p.invoiceLines.filter(l=>l&&l.invoiceId):[];
  const isSplit=lines.length>1;
  const available=(r)=>r.fields&&!(r.fields.QBPaymentId)&&!claimed.has(r.id)&&notSuperseded(r);
  const amtMatchVal=(r,v)=>{const a=money(r.fields.Amount);return a!==null&&v!==null&&Math.abs(a-v)<0.005;};

  if(!isSplit){
    // ---- single-invoice payment: same behavior as before ----
    const firstInvId=lines.length?String(lines[0].invoiceId):((p.invoiceIds&&p.invoiceIds.length)?String(p.invoiceIds[0]):null);
    const invMeta=firstInvId?invById[firstInvId]:null;
    const invoiceNumber=invMeta?invMeta.docNumber:'';
    const seen=rows.find(r=>r.fields&&notSuperseded(r)&&String(r.fields.QBPaymentId||'')===String(p.qbPaymentId));
    if(seen) continue;
    let action,airtableRowId='',backfillStatus='';
    let match=null;
    // 1) strongest: same check number + same amount
    if(p.refNum){match=rows.find(r=>available(r)&&String(r.fields.CheckNumber||'')===String(p.refNum)&&amtMatchVal(r,amt));}
    // 2) fallback: same invoice # + same amount (covers a blank/different QB reference field)
    if(!match&&invoiceNumber){match=rows.find(r=>available(r)&&String(r.fields.InvoiceNumber||'')===String(invoiceNumber)&&amtMatchVal(r,amt));}
    if(match){action='backfill';airtableRowId=match.id;claimed.add(match.id);backfillStatus=String((match.fields&&match.fields.Status)||'');} else {action='record';}
    if(action==='record'&&!invoiceNumber) continue;
    out.push({json:{_action:action,airtableRowId,_backfillStatus:backfillStatus,qbPaymentId:p.qbPaymentId,refNum:p.refNum||'',amount:amt,method:p.method||'',txnDate:p.txnDate||'',customerName:p.customerName||'',customerRefId:p.customerRefId||'',invoiceNumber,invFull:(invMeta&&invMeta.full!=null)?invMeta.full:null,invTotal:invMeta?invMeta.total:null,invBalance:invMeta?invMeta.balance:null,isSplit:false,splitGroup:'',splitCount:1,splitIndex:1,splitCheckTotal:amt}});
    continue;
  }

  // ---- multi-invoice payment: one work item per invoice line ----
  const parts=lines.map(l=>{
    const meta=invById[String(l.invoiceId)]||null;
    return {invoiceId:String(l.invoiceId),lineAmount:money(l.amount),docNumber:meta?meta.docNumber:'',invTotal:meta?meta.total:null,invBalance:meta?meta.balance:null,invFull:(meta&&meta.full!=null)?meta.full:null};
  }).filter(pt=>pt.docNumber);
  if(!parts.length) continue;
  const partExists=(pt)=>rows.some(r=>r.fields&&notSuperseded(r)&&String(r.fields.QBPaymentId||'')===String(p.qbPaymentId)&&digitsOf(r.fields.InvoiceNumber)===digitsOf(pt.docNumber));
  const partsNeeded=parts.filter(pt=>!partExists(pt));
  if(!partsNeeded.length) continue; // every invoice on this payment already has its own row
  // If the check-bot already logged this physical check as ONE full-amount row,
  // claim it and mark it superseded so amounts are never double-counted.
  if(p.refNum){
    const parent=rows.find(r=>available(r)&&String(r.fields.CheckNumber||'')===String(p.refNum)&&amtMatchVal(r,amt));
    if(parent){claimed.add(parent.id);out.push({json:{_action:'backfill',airtableRowId:parent.id,_backfillStatus:'superseded_split',qbPaymentId:p.qbPaymentId,refNum:p.refNum||'',amount:amt,method:p.method||'',txnDate:p.txnDate||'',customerName:p.customerName||'',customerRefId:p.customerRefId||''}});}
  }
  let idx=0;
  for(const pt of partsNeeded){
    idx++;
    out.push({json:{_action:'record',airtableRowId:'',_backfillStatus:'',qbPaymentId:p.qbPaymentId,refNum:p.refNum||'',amount:pt.lineAmount,method:p.method||'',txnDate:p.txnDate||'',customerName:p.customerName||'',customerRefId:p.customerRefId||'',invoiceNumber:pt.docNumber,invFull:pt.invFull,invTotal:pt.invTotal,invBalance:pt.invBalance,isSplit:true,splitGroup:String(p.qbPaymentId),splitCount:parts.length,splitIndex:idx,splitCheckTotal:amt}});
  }
}
return out;

// The original Airtable dedup formula, verbatim in JS: live qb_payment_id
// check first, then the register snapshot for check#/invoice+amount matches.
const p = $('Loop Over Payments').item.json;
const digits = s => String(s == null ? '' : s).replace(/[^0-9]/g, '');
const money = v => { const n = parseFloat(v); return isNaN(n) ? null : Math.round(n * 100) / 100; };
const amt = money(p.amount);
const live = ($json.items || []).filter(r => r.status !== 'superseded_split');
if (live.length) return { json: Object.assign({}, p, { _dupId: live[0].review_item_id }) };
const rows = $('Rows As Register').all().map(it => it.json)
  .filter(r => r && r.id && r.fields)
  .filter(r => String(r.fields.Status || '') !== 'superseded_split');
const invD = digits(p.invoiceNumber), refD = digits(p.refNum);
const amtEq = r => { const a = money(r.fields.Amount); return a !== null && amt !== null && Math.abs(a - amt) < 0.005; };
let hit = null;
if (p.isSplit) {
  hit = rows.find(r => String(r.fields.QBPaymentId || '') === String(p.qbPaymentId) && digits(r.fields.InvoiceNumber) === invD)
     || (invD ? rows.find(r => !(r.fields.QBPaymentId) && digits(r.fields.InvoiceNumber) === invD && amtEq(r)) : null);
} else {
  hit = rows.find(r => String(r.fields.QBPaymentId || '') === String(p.qbPaymentId))
     || (refD ? rows.find(r => digits(r.fields.CheckNumber) === refD && ((invD && digits(r.fields.InvoiceNumber) === invD) || amtEq(r))) : null)
     || (invD ? rows.find(r => !(r.fields.QBPaymentId) && digits(r.fields.InvoiceNumber) === invD && amtEq(r)) : null);
}
return { json: Object.assign({}, p, { _dupId: hit ? hit.id : '' }) };

