const job=$json;
const p=$('Loop Over Payments').item.json;
function money(v){const n=parseFloat(v);return isNaN(n)?null:Math.round(n*100)/100;}
function fmt(n){if(n==null)return '?';let p=Number(n).toFixed(2).split('.');p[0]=p[0].replace(/\B(?=(\d{3})+(?!\d))/g,',');return p[0]+'.'+p[1];}
const amt=money(p.amount);
const isSplit=!!p.isSplit;
const total=(p.invTotal!=null)?Number(p.invTotal):null;
const bal=(p.invBalance!=null)?Number(p.invBalance):null;
const paidSoFar=(total!=null&&bal!=null)?(total-bal):null;
const priorPaid=(paidSoFar!=null&&amt!=null)?(paidSoFar-amt):null;
const F=(p.invFull!=null&&total!=null)?Math.max(Number(p.invFull),total):((p.invFull!=null)?Number(p.invFull):total); // full contract from line details (Rate x1); = invoice total when no fractional-qty lines
const fracInv=(F!=null&&total!=null&&F>total+0.01);
let ptype='payment';
if(total!=null&&bal!=null&&amt!=null){
  if(paidSoFar>=F-0.01) ptype=(priorPaid>0.01)?'remainder':'PIF';
  else ptype=(priorPaid>0.01)?'progress':'deposit';
}
const typeLabel=(ptype==='PIF')?'paid in full':((ptype==='progress')?'progress payment':ptype);
const priorPaidStr=(priorPaid!=null&&priorPaid>0.01)?('$'+fmt(priorPaid)):null;
const remainStr=(bal!=null)?('$'+fmt(Math.max(0,bal))):null;
let ctx='';
if(priorPaidStr){ ctx=(bal!=null&&bal<=0.01)?(priorPaidStr+' previously paid \u00b7 pays the invoice in full'):(remainStr?(priorPaidStr+' previously paid \u00b7 '+remainStr+' remaining'):(priorPaidStr+' previously paid')); }
if(fracInv&&paidSoFar!=null){ const extra='75%-style invoice \u00b7 full contract $'+fmt(F)+' \u00b7 collected $'+fmt(paidSoFar); ctx=ctx?(ctx+' \u00b7 '+extra):extra; }
const splitNote=isSplit?(' \u00b7 one '+(p.method||'payment')+(p.refNum?(' #'+p.refNum):'')+' of $'+fmt(p.splitCheckTotal)+' covered '+p.splitCount+' invoices; this is the portion for invoice #'+p.invoiceNumber):'';
const GROUP='120363000000000000@g.us';
return { json: {
  Status:'confirmed', QBPaymentId:p.qbPaymentId, PaymentMethod:p.method, PaymentDate:p.txnDate, Source:'sweep',
  CheckNumber:p.refNum||'', Amount:amt, InvoiceNumber:p.invoiceNumber, PaymentType:ptype, PayerName:p.customerName,
  JobName:job.CustomerName||'', JobId:job.JobId, MorawareURL:job.LeadUrl||'', MatchMethod:'invoice:'+(job.Source||''), GroupJID:GROUP,
  SplitGroup:(p.splitGroup||''), _sendNow:!isSplit,
  _postNote:true, jobId:job.JobId, groupJID:GROUP,
  noteText:'\ud83d\udcb5 Payment recorded \u2014 $'+fmt(amt)+' \u00b7 '+p.method+' \u00b7 invoice #'+p.invoiceNumber+' ('+typeLabel+', received '+p.txnDate+')'+(ctx?(' \u00b7 '+ctx):'')+splitNote+'. Logged by the payment bot.',
  messageText:'\u2705 New payment recorded\n$'+fmt(amt)+' \u00b7 '+p.method+' \u00b7 invoice #'+p.invoiceNumber+'\nJob: '+(job.CustomerName||'(unknown)')+(job.LeadUrl?('\n'+job.LeadUrl):'')+'\nType: '+typeLabel+(ctx?('\n'+ctx):'')+'\nLogged in Airtable + Moraware note added. No action needed.'
}};

const qr=$json.QueryResponse||{};
const cust=(Array.isArray(qr.Customer)&&qr.Customer[0])?qr.Customer[0]:{};
const addr=cust.BillAddr||{};
const line1=(addr.Line1||'').toString().trim();
const m=line1.match(/^\s*(\d+)\s+(.*)$/);
const street_number=m?m[1]:'';
const street_name=m?m[2].trim():line1;
const zip=(addr.PostalCode||'').toString().trim().slice(0,5);
const given=(cust.GivenName||'').toString().trim();
const middle=(cust.MiddleName||'').toString().trim();
const family=(cust.FamilyName||'').toString().trim();
const display=(cust.DisplayName||cust.CompanyName||'').toString().trim();
const isOrg=(!given&&!family&&!!display);
const additional=[]; if(display)additional.push(display);
return { json: {
  first_name:given, middle_name:middle, last_name:family||(isOrg?display:''),
  entity_type:isOrg?'organization':'individual',
