const r = $input.item.json;
const matches = Array.isArray(r.Matches) ? r.Matches : [];
const strategy = r.MatchedStrategy || 'none';
const ambiguous = !!r.Ambiguous;

function pick(list){ return list.length ? list[0] : null; } // already newest-first

let chosen=null, chosenKind='none';
if (matches.length){
  const strong = matches.filter(m => m.NameMatchStrength === 'strong');
  if (strong.length){ chosen = pick(strong); chosenKind='strong'; }
  else { chosen = pick(matches); chosenKind='weak'; }
}

// address-ambiguous: don't auto-pick one; force the manager to choose a unit
const addressAmbiguous = (strategy === 'address' && ambiguous && matches.length > 1);

return { json: {
  found: matches.length > 0,
  strategy,
  ambiguous: addressAmbiguous,
  chosen_kind: chosenKind,
  match_count: matches.length,
  job_id: chosen ? chosen.JobId : null,
  job_name: chosen ? chosen.CustomerName : null,
  lead_url: chosen ? chosen.LeadUrl : null,
  creation_date: chosen ? chosen.CreationDate : null,
  // keep the full list for the ambiguous-address message
  all_matches: matches
}};

