// NF Collect - accept only an exactly-one-strong, unambiguous match; first candidate wins
const cands = $('NF Candidates').all();
const resp = $input.all();
let win = null, winKind = '';
for (let i = 0; i < resp.length; i++) {
  const c = cands[i] ? cands[i].json : {};
  if (c._skip) continue;
  const r = (resp[i] && resp[i].json) || {};
  const ms = Array.isArray(r.Matches) ? r.Matches : [];
  const strong = ms.filter(m => m && m.NameMatchStrength === 'strong');
  if (!r.Ambiguous && strong.length === 1) { win = strong[0]; winKind = c._kind; break; }
}
if (win) return [{ json: { found: true, strategy: winKind, ambiguous: false, chosen_kind: 'strong',
  match_count: 1, job_id: win.JobId, job_name: win.CustomerName, lead_url: win.LeadUrl,
  creation_date: win.CreationDate || null, all_matches: [win] } }];
return [{ json: { found: false, strategy: 'none', ambiguous: false, chosen_kind: 'none',
  match_count: 0, job_id: null, job_name: null, lead_url: null, creation_date: null, all_matches: [] } }];

