const bal=(p.invBalance!=null)?Number(p.invBalance):null;
const paidSoFar=(total!=null&&bal!=null)?(total-bal):null;
const priorPaid=(paidSoFar!=null&&amt!=null)?(paidSoFar-amt):null;
const F=(p.invFull!=null&&total!=null)?Math.max(Number(p.invFull),total):((p.invFull!=null)?Number(p.invFull):total); // full contract from line details (Rate x1); = invoice total when no fractional-qty lines
const fracInv=(F!=null&&total!=null&&F>total+0.01);
let ptype='payment';
if(total!=null&&bal!=null&&amt!=null){
  if(paidSoFar>=F-0.01) ptype=(priorPaid>0.01)?'remainder':'PIF';
  else ptype=(priorPaid>0.01)?'progress':'deposit';
}
const typeLabel=(ptype==='PIF')?'paid in full':((ptype==='progress')?'progress payment':ptype);
const priorPaidStr=(priorPaid!=null&&priorPaid>0.01)?('$'+fmt(priorPaid)):null;
const remainStr=(bal!=null)?('$'+fmt(Math.max(0,bal))):null;
let ctx='';
if(priorPaidStr){ ctx=(bal!=null&&bal<=0.01)?(priorPaidStr+' previously paid \u00b7 pays the invoice in full'):(remainStr?(priorPaidStr+' previously paid \u00b7 '+remainStr+' remaining'):(priorPaidStr+' previously paid')); }
if(fracInv&&paidSoFar!=null){ const extra='75%-style invoice \u00b7 full contract $'+fmt(F)+' \u00b7 collected $'+fmt(paidSoFar); ctx=ctx?(ctx+' \u00b7 '+extra):extra; }
const GROUP='120363000000000000@g.us';
return { json: {
  Status:'needs_job', QBPaymentId:p.qbPaymentId, PaymentMethod:p.method, PaymentDate:p.txnDate, Source:'sweep',
  CheckNumber:p.refNum||'', Amount:amt, InvoiceNumber:p.invoiceNumber, PaymentType:ptype, PayerName:p.customerName,
  JobName:'', JobId:null, MorawareURL:'', MatchMethod:'none', GroupJID:GROUP,
  SplitGroup:(p.splitGroup||''), _sendNow:!isSplit,
  _postNote:false, jobId:0, groupJID:GROUP, noteText:'',
  messageText:'\u26a0\ufe0f New payment needs a job\n$'+fmt(amt)+' \u00b7 '+p.method+' \u00b7 invoice #'+p.invoiceNumber+'\nCustomer (QB): '+(p.customerName||'(unknown)')+'\nCould not match by invoice #, address, or customer name. Please add invoice #'+p.invoiceNumber+' to the correct Moraware job. Logged as needs-job.'
}};

